arguments.command:
cd /app; grep -c . /tmp/sum.txt; grep -n "Interrupt\|cancel" logs/ci/* | head; grep -h -A1 "^---- ERROR" /tmp/sum.txt | head -0; python3 - <<'E'
import re
t=open('/tmp/sum.txt').read()
cur=None; seen={}
for l in t.split('\n'):
    if l.startswith('#####'): cur=l
    elif l.startswith('---- '): name=l
    elif l.strip().startswith('['):
        key=(name,re.sub(r'\d','#',l.strip())[:150])
        seen.setdefault(key,[]).append(cur.split()[1]+' '+' '.join(cur.split()[2:5]))
for k,v in sorted(seen.items()): print(k[0][5:],k[1],len(v),v[:3])
E

